            let owned: Box<[u8]> = k.into();
            let by_ref: Box<[u8]> = (&k).into();
            assert_eq!(
                owned, by_ref,
                "impossibility {k:?}: From<Kind> for Box<[u8]> and From<&Kind> for Box<[u8]> must agree",
            );
